package qr

// Reed-Solomon error correction for QR Code symbols, over the field GF(256)
// generated by the primitive polynomial x^8 + x^4 + x^3 + x^2 + 1 (0x11D) with
// 2 as the primitive element. ISO/IEC 18004 fixes both choices, so these are
// not tunable.

const gfPrimitive = 0x11d

// gfExp holds 2^i for i in 0..511. The table is doubled so a product of two
// logarithms can be looked up without a modulo. gfLog is its inverse;
// gfLog[0] is unused because zero has no logarithm.
var (
	gfExp [512]byte
	gfLog [256]int
)

func init() {
	x := 1
	for i := 0; i < 255; i++ {
		gfExp[i] = byte(x)
		gfLog[x] = i
		x <<= 1
		if x&0x100 != 0 {
			x ^= gfPrimitive
		}
	}
	for i := 255; i < 512; i++ {
		gfExp[i] = gfExp[i-255]
	}
}

// gfMul multiplies in GF(256). Addition in the field is XOR.
func gfMul(a, b byte) byte {
	if a == 0 || b == 0 {
		return 0
	}
	return gfExp[gfLog[a]+gfLog[b]]
}

// rsGeneratorPoly returns the generator polynomial of degree n, the product of
// (x - 2^i) for i in 0..n-1, as coefficients from the highest power down. The
// leading coefficient is always 1 and is omitted, so the slice has n entries.
func rsGeneratorPoly(n int) []byte {
	poly := []byte{1}
	for i := 0; i < n; i++ {
		// Multiply poly by (x - 2^i).
		root := gfExp[i]
		next := make([]byte, len(poly)+1)
		for j, c := range poly {
			next[j] ^= c
			next[j+1] ^= gfMul(c, root)
		}
		poly = next
	}
	return poly[1:]
}

// rsRemainder returns the n error-correction codewords for data: the remainder
// of data * x^n divided by the degree-n generator polynomial.
func rsRemainder(data []byte, n int) []byte {
	if n == 0 {
		return nil
	}
	gen := rsGeneratorPoly(n)
	rem := make([]byte, n)
	for _, b := range data {
		factor := b ^ rem[0]
		copy(rem, rem[1:])
		rem[n-1] = 0
		for i, g := range gen {
			rem[i] ^= gfMul(g, factor)
		}
	}
	return rem
}

// rsSyndromes evaluates the codeword polynomial at the n roots of the
// generator polynomial, 2^0 .. 2^(n-1). Every syndrome
// is zero exactly when the codeword is a valid Reed-Solomon codeword, so this
// is how a reader tells an intact block from a damaged one. This encoder does
// not implement error *correction*: a block that fails here is reported as
// unreadable rather than repaired, which is the safe direction for a signed
// payload — a half-repaired passport must never be presented as genuine.
func rsSyndromes(codeword []byte, n int) []byte {
	out := make([]byte, n)
	for i := 0; i < n; i++ {
		var acc byte
		root := gfExp[i]
		for _, c := range codeword {
			acc = gfMul(acc, root) ^ c
		}
		out[i] = acc
	}
	return out
}
